/* crosswalk cards, r26. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26a"]=[{"q": "If Σ |zₖ| settles, then Σ zₖ settles. What is this on the page?", "a": "the plane-size technique", "w": ["the turn-growth technique", "the comparison technique", "the growth-and-turn technique"], "why": "22e’s settles-in-size technique, applied to the floor and upright parts."}, {"q": "z = (1 + i)/2. Where does Σ zᵏ (from k = 0) settle?", "a": "1 + i", "w": ["2", "1 − i", "it wanders"], "why": "1/(1 − z) = 2/(1 − i) = 1 + i; |z| ≈ 0.707 < 1."}, {"q": "For which complex z does 1 + z + z²/2! + z³/3! + ⋯ settle?", "a": "every z", "w": ["only |z| < 1", "only real z", "only |z| ≤ e"], "why": "Its sizes add to e^|z|, a real sum that settles."}, {"q": "For real θ, e^(iθ) = cos θ + i sin θ. What is this on the page?", "a": "the turn-growth technique", "w": ["the plane-size technique", "the out-and-round form", "the whole-turn technique"], "why": "Even pieces give the cosine sum, odd pieces i times the sine sum."}, {"q": "In the turn-growth proof, the line ‘= Σ(−1)ᵐθ²ᵐ/(2m)! + iΣ(−1)ᵐθ²ᵐ⁺¹/(2m+1)!’ follows from what?", "a": "i²ᵐ = (−1)ᵐ and i²ᵐ⁺¹ = (−1)ᵐi", "w": ["the sums for sin and cos (23b2)", "the plane-size technique", "cos² θ + sin² θ = 1"], "why": "The sums for sin and cos come in the next line."}, {"q": "What is e^(iπ)?", "a": "−1", "w": ["1", "i", "0"], "why": "cos π = −1, sin π = 0."}, {"q": "What is e^(iπ/3), as a + bi?", "a": "½ + (√3/2)i", "w": ["(√3/2) + ½i", "½ − (√3/2)i", "1 + (π/3)i"], "why": "cos(π/3) = ½, sin(π/3) = √3/2."}, {"q": "What is |e^(iθ)| for real θ?", "a": "1", "w": ["e^θ", "θ", "e"], "why": "√(cos² θ + sin² θ) = 1: it turns, it does not grow."}, {"q": "−2 written as a length times e to a turn:", "a": "2e^(iπ)", "w": ["−2e^(i0)", "2e^(−iπ/2)", "e^(2iπ)"], "why": "Length 2, half a turn."}, {"q": "Σ iᵏ/k settles. Does Σ |iᵏ/k| settle?", "a": "no: it is Σ 1/k", "w": ["yes, by the plane-size technique", "yes, at the same total", "only its floor part does"], "why": "The settles-in-size technique runs one way only."}, {"q": "e^(2πi) = 1 = e⁰. What follows?", "a": "nothing about 2πi = 0: e^z repeats every whole turn", "w": ["2πi = 0", "e^z is one-to-one on ℂ", "2π = 0"], "why": "Every 2πik gives 1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26b"]=[{"q": "For all complex z and w, e^(z + w) = e^z e^w. What is this on the page?", "a": "the plane-adding technique", "w": ["the growth-and-turn technique", "the turn-growth technique", "the whole-turn technique"], "why": "Multiply the two sums; each group is a binomial."}, {"q": "In the plane-adding proof, cₙ = (z + w)ⁿ/n! follows from what?", "a": "the two-term-power technique (4k)", "w": ["the product technique (23h4)", "the plane-size technique", "the turn-growth technique"], "why": "The product technique gives the grouping; 4k sums each group."}, {"q": "e^(a + bi) = e^a(cos b + i sin b). What is this on the page?", "a": "the growth-and-turn technique", "w": ["the turn-growth technique", "the plane-adding technique", "the plane-log technique"], "why": "The floor part grows, the upright part turns."}, {"q": "What is |e^(3 + 4i)|?", "a": "e³", "w": ["e⁵", "e⁷", "e⁴"], "why": "|e^(a+bi)| = e^a."}, {"q": "e^(2 + iπ/3), as a + bi to two places:", "a": "3.69 + 6.40i", "w": ["7.39 + 1.05i", "1 + 1.73i", "0.50 + 0.87i"], "why": "e²(½ + (√3/2)i)."}, {"q": "Which z have |e^z| = 1?", "a": "those with floor part 0", "w": ["only z = 0", "those of size 1", "those with upright part 0"], "why": "|e^z| = e^a = 1 exactly when a = 0."}, {"q": "e^z = 1 exactly when z = 2πik. What is this on the page?", "a": "the whole-turn technique", "w": ["the growth-and-turn technique", "the plane-adding technique", "the main-log technique"], "why": "Size 1 forces a = 0; turn 1 forces whole turns."}, {"q": "Every z with e^z = −1:", "a": "(2k + 1)πi, k whole", "w": ["πi only", "2πki", "−1 + 2πki"], "why": "Size 1, turn π, plus whole turns."}, {"q": "Why is e^z never 0?", "a": "e^z e^(−z) = 1", "w": ["e^z grows", "|e^z| = e^|z|", "e^z is one-to-one"], "why": "A product equal to 1 has no factor 0."}, {"q": "Multiplying by e^z, z = a + bi, does what to the plane?", "a": "stretches by e^a and turns by b", "w": ["stretches by e^b and turns by a", "stretches by |z| and turns by a", "turns by z"], "why": "Growth for the length, turning for the angle."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26c"]=[{"q": "Every z ≠ 0 has the logarithms ln|z| + i(θ + 2πk). What is this on the page?", "a": "the plane-log technique", "w": ["the main-log technique", "the whole-turn technique", "the many-powers technique"], "why": "One log from out and round, the rest by whole turns."}, {"q": "Every logarithm of −1:", "a": "(2k + 1)πi", "w": ["0", "iπ only", "2πki"], "why": "r = 1, θ = π, plus whole turns."}, {"q": "Log z = ln|z| + iθ with θ in which range?", "a": "(−π, π]", "w": ["[0, 2π)", "[−π, π]", "(−π/2, π/2]"], "why": "One half turn either side of 0, with π kept and −π left out."}, {"q": "What is Log(−1 − i)?", "a": "½ ln 2 − 3πi/4", "w": ["½ ln 2 + 5πi/4", "ln 2 − 3πi/4", "½ ln 2 + 3πi/4"], "why": "Size √2, main turn −3π/4."}, {"q": "Log(−1) + Log(−1) = 2πi, Log((−1)(−1)) = 0. Which technique sets the gap?", "a": "the main-log technique", "w": ["the plane-log technique", "the plane-adding technique", "the many-powers technique"], "why": "Log(zw) = Log z + Log w + 2πik, k in {−1, 0, 1}."}, {"q": "Does Log(i · i) = Log i + Log i?", "a": "yes: both are iπ", "w": ["no: they differ by 2πi", "no: Log(−1) = −iπ", "only up to sign"], "why": "The turns add to π, which is in (−π, π]."}, {"q": "How many values has 1^(1/3)?", "a": "3", "w": ["1", "2", "endlessly many"], "why": "Equal parts of a turn: e^(2πik/3)."}, {"q": "The main value of i^i:", "a": "e^(−π/2) ≈ 0.2079", "w": ["−1", "e^(π/2)", "i"], "why": "i · Log i = i · iπ/2 = −π/2: real."}, {"q": "z^w has endlessly many values when…", "a": "w is not a fraction", "w": ["w is whole", "w = 1/n", "z is negative"], "why": "(k − k′)w whole forces k = k′."}, {"q": "Why has 0 no logarithm?", "a": "e^w is never 0", "w": ["ln 0 = −∞", "0 has no turn", "log is many-valued"], "why": "The growth-and-turn technique."}, {"q": "Log(e^(2πi)) equals…", "a": "0", "w": ["2πi", "1", "−2πi"], "why": "e^(2πi) = 1 and Log 1 = 0."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26d"]=[{"q": "Sums, products, quotients and chains of functions with complex slopes have them. What is this on the page?", "a": "the plane-slope technique", "w": ["the two-ways technique", "the plane-exp-slope technique", "the path-ends technique"], "why": "Rung 13’s techniques, whose proofs hold in ℂ."}, {"q": "What is the complex slope of z³ − 2iz + 5?", "a": "3z² − 2i", "w": ["3z² − 2iz", "3z²", "z² − 2i"], "why": "Powers and constants, by the plane-slope technique."}, {"q": "What is (1/(z − i))′, and where?", "a": "−1/(z − i)², for z ≠ i", "w": ["1/(z − i)², everywhere", "−1/(z − i)², everywhere", "ln(z − i)"], "why": "The quotient technique; no value at i."}, {"q": "exp′ = exp on ℂ. What is this on the page?", "a": "the plane-exp-slope technique", "w": ["the plane-slope technique", "the plane-adding technique", "the turn-growth technique"], "why": "(e^h − 1)/h heads to 1."}, {"q": "In the plane-exp-slope proof, (e^(z+h) − e^z)/h = e^z(e^h − 1)/h. What licenses it?", "a": "the plane-adding technique", "w": ["the plane-slope technique", "the growth-and-turn technique", "the turn-growth technique"], "why": "e^(z+h) = e^z e^h."}, {"q": "A complex slope forces the upright rise over run to match the floor one. What is this on the page?", "a": "the two-ways technique", "w": ["the plane-slope technique", "the flip technique", "the path-fence technique"], "why": "Two directions are special cases of every direction."}, {"q": "For f = z̄, the rise over run along the floor and along the upright:", "a": "1 and −1", "w": ["1 and 1", "−1 and −1", "0 and 0"], "why": "t̄/t = 1, (it)̄/(it) = −1."}, {"q": "Where does |z|² have a complex slope?", "a": "only at 0", "w": ["everywhere", "nowhere", "on the floor"], "why": "2x₀ = −2iy₀ only at 0; there |h|²/h = h̄ → 0."}, {"q": "What is the complex slope of z e^(−z)?", "a": "(1 − z)e^(−z)", "w": ["−z e^(−z)", "e^(−z)", "(1 + z)e^(−z)"], "why": "Product and chain techniques."}, {"q": "u and v are smooth in x and y. Must f = u + iv have a complex slope?", "a": "no: the flip is a counterexample", "w": ["yes, always", "yes, if u and v are polynomials", "only at 0"], "why": "u = x, v = −y; no complex slope anywhere."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26e"]=[{"q": "|∫_γ f dz| ≤ ML. What is this on the page?", "a": "the path-fence technique", "w": ["the path-ends technique", "the circle-powers technique", "the plane-triangle technique"], "why": "M bounds |f| on the path, L is its length."}, {"q": "If F′ = f near the path, ∫_γ f dz = F(end) − F(start). What is this on the page?", "a": "the path-ends technique", "w": ["the path-fence technique", "the circle-powers technique", "the disc-undoing technique"], "why": "The chain technique along the path, then 16c."}, {"q": "Once round |z| = r anticlockwise, ∫ zⁿ dz is 2πi for n = −1 and 0 otherwise. What is this on the page?", "a": "the circle-powers technique", "w": ["the path-ends technique", "the hole technique", "the residue technique"], "why": "Whole turns of cos and sin cancel, except m = 0."}, {"q": "∫ z dz along the straight path from 0 to 1 + i:", "a": "i", "w": ["1", "1 + i", "0"], "why": "(1 + i)²/2 = i."}, {"q": "∫ z̄ dz along the straight path from 0 to 1 + i:", "a": "1", "w": ["i", "−i", "0"], "why": "t(1 − i)(1 + i) = 2t, area 1."}, {"q": "∫ e^z dz along any path from 0 to iπ:", "a": "−2", "w": ["0", "2", "iπ"], "why": "e^(iπ) − e⁰."}, {"q": "∮ (3/z + z) dz once round |z| = 2:", "a": "6πi", "w": ["0", "2πi", "12πi"], "why": "3 · 2πi + 0."}, {"q": "Why does ∮ dz/z round |z| = 1 not equal [Log z] = 0?", "a": "Log jumps at −1: no undoing goes all the way round", "w": ["the circle is too small", "1/z has no slope at 1", "the path fence forbids it"], "why": "Log goes from −iπ to iπ: a whole turn."}, {"q": "In the circle-powers proof, γ′(t) = ire^(it). What licenses it?", "a": "the plane-exp-slope technique, through the chain technique (26d2)", "w": ["the plane-size technique", "the path-fence technique", "the whole-turn technique"], "why": "The slope of e^(it) in t is ie^(it)."}, {"q": "Does ∮ dz/z round |z| = r depend on r?", "a": "no: always 2πi", "w": ["yes: 2πir", "yes: 2πi/r", "yes: 2πr"], "why": "The rⁿ⁺¹ is r⁰ = 1 when n = −1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26f"]=[{"q": "A function with a complex slope on an open set holding a triangle totals 0 round it. What is this on the page?", "a": "the triangle-total technique", "w": ["the disc-undoing technique", "the path-ends technique", "the hole technique"], "why": "Cut into four, keep the worst quarter, repeat."}, {"q": "In the triangle-total proof, one of the four quarters has a total at least ¼ of the whole. What licenses it?", "a": "the plane-triangle technique (25c2)", "w": ["the path-fence technique", "the crowd technique (22c2)", "the path-ends technique"], "why": "Four totals add to the whole; not all can be small."}, {"q": "In the triangle-total proof, the corners of Tₙ head to one point z₀. What licenses it?", "a": "the crowd technique (22c2)", "w": ["the path-fence technique", "the triangle-total technique", "the plane-size technique"], "why": "Nested closed triangles whose sides halve."}, {"q": "In that proof, ∮ round Tₙ of f(z₀) + f′(z₀)(z − z₀) is 0. What licenses it?", "a": "the path-ends technique (26e2)", "w": ["the circle-powers technique", "the plane-size technique", "the hole technique"], "why": "A line has an undoing."}, {"q": "A continuous f with a complex slope on a disc, but at most one point, has an undoing there. What is this on the page?", "a": "the disc-undoing technique", "w": ["the triangle-total technique", "the path-ends technique", "the rim technique"], "why": "F(z) = ∫ from the centre to z."}, {"q": "1/z totals 2πi round |z| = 1, so it has no undoing round 0. What is this on the page?", "a": "the hole technique", "w": ["the circle-powers technique", "the disc-undoing technique", "the path-fence technique"], "why": "An undoing would force total 0."}, {"q": "∮ z̄ dz round the triangle 0 → 1 → i → 0:", "a": "i", "w": ["0", "2πi", "½"], "why": "½ + i − ½; z̄ has no complex slope."}, {"q": "∮ 1/(z − 5) dz round |z| = 3:", "a": "0", "w": ["2πi", "−2πi", "2πi/5"], "why": "A slope on |z| < 4: disc-undoing."}, {"q": "∮ 1/z dz round |z − 1| = 2:", "a": "2πi", "w": ["0", "πi", "4πi"], "why": "The circle holds 0; geometric sum in 1/(z − 1), term by term."}, {"q": "Why does the disc-undoing technique fail on the ring ½ < |z| < 2?", "a": "no centre sees every point by a segment inside the ring", "w": ["1/z has no slope on the ring", "the ring is not bounded", "the ring holds 0"], "why": "The segment from 1 to −1 crosses 0."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26g"]=[{"q": "f(z) = (1/2πi)∮ f(w)/(w − z) dw for z inside C. What is this on the page?", "a": "the rim technique", "w": ["the rebuilt-in-the-plane technique", "the residue technique", "the circle-powers technique"], "why": "The rim fixes the inside."}, {"q": "In the rim proof, ∮ g = 0 for g(w) = (f(w) − f(z))/(w − z). What licenses it?", "a": "the disc-undoing technique, one point excepted", "w": ["the triangle-total technique", "the path-ends technique", "the circle-powers technique"], "why": "g is continuous, with a slope everywhere but z."}, {"q": "A function with a complex slope on a disc is a power sum there. What is this on the page?", "a": "the rebuilt-in-the-plane technique", "w": ["the rim technique", "the smooth-sum technique", "the bounded-constant technique"], "why": "Expand the rim kernel as a geometric sum."}, {"q": "The fence on the coefficients given by the rebuilt-in-the-plane technique:", "a": "|uₖ| ≤ M/rᵏ", "w": ["|uₖ| ≤ M rᵏ", "|uₖ| ≤ M/k!", "|uₖ| ≤ 2πM"], "why": "The path fence on the coefficient integral."}, {"q": "A function with a complex slope everywhere and |f| ≤ M is constant. What is this on the page?", "a": "the bounded-constant technique", "w": ["the rim technique", "the root technique", "the far-out technique"], "why": "Let r grow in |uₖ| ≤ M/rᵏ."}, {"q": "∮ e^w/(w − 1) dw round |w| = 2:", "a": "2πie", "w": ["2πi", "0", "2πie²"], "why": "Rim technique: 2πi f(1)."}, {"q": "Reach of the power sum of 1/(1 + z²) about 1:", "a": "√2", "w": ["1", "2", "∞"], "why": "Distance from 1 to ±i."}, {"q": "|sin(iy)| for y = 1, to four places:", "a": "1.1752", "w": ["0.8415", "1", "0.5403"], "why": "sin(iy) = i(e^y − e^(−y))/2."}, {"q": "Why can e^(−1/x²) be smooth on the line yet not a power sum?", "a": "it has no complex slope on any disc round 0", "w": ["its slopes at 0 are not 0", "it is not continuous on the line", "it grows too fast on the line"], "why": "Along the upright it passes every ceiling."}, {"q": "In the two-line root proof, 1/p bounded follows from what?", "a": "the far-out and lowest-size techniques (25d1, 25d2)", "w": ["the bounded-constant technique", "the rim technique", "the plane-slope technique"], "why": "Far out |p| is big; on the disc |p| has a least value above 0."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26h"]=[{"q": "Near a pole of order m, f = bₘ/(z − w)ᵐ + ⋯ + b₁/(z − w) + h(z). What is this on the page?", "a": "the pole-split technique", "w": ["the residue technique", "the rebuilt-in-the-plane technique", "the root-count technique"], "why": "Divide g’s power sum by (z − w)ᵐ."}, {"q": "∮_C f = 2πi times the sum of the residues inside. What is this on the page?", "a": "the residue technique", "w": ["the rim technique", "the circle-powers technique", "the pole-split technique"], "why": "Only the 1/(z − w) pieces survive a loop."}, {"q": "(1/2πi)∮ p′/p counts the roots inside C. What is this on the page?", "a": "the root-count technique", "w": ["the root technique", "the residue technique", "the bounded-constant technique"], "why": "p′/p = Σ 1/(z − rⱼ), each with residue 1."}, {"q": "In the residue proof, ∮ dz/(z − wⱼ)ᵏ = 0 for k ≥ 2. What licenses it?", "a": "the path-ends technique (26e2)", "w": ["the disc-undoing technique", "the rim technique", "the triangle-total technique"], "why": "It has the undoing −1/((k − 1)(z − wⱼ)ᵏ⁻¹)."}, {"q": "The residue of 1/(z² + 1) at i:", "a": "−i/2", "w": ["i/2", "1/2", "1"], "why": "1/(2i) = −i/2."}, {"q": "The residue of e^z/z³ at 0:", "a": "½", "w": ["1", "0", "1/6"], "why": "b₁ = g₂ = 1/2!."}, {"q": "∮ 1/(z² + 1) dz round |z − i| = 1:", "a": "π", "w": ["0", "2π", "πi"], "why": "2πi · (−i/2); −i lies outside."}, {"q": "The residue of 1/z² at 0:", "a": "0", "w": ["1", "2", "−1"], "why": "There is no 1/z piece."}, {"q": "∮ e^z/(z(z − 1)) dz round |z| = 2:", "a": "2πi(e − 1)", "w": ["2πie", "0", "2πi(e + 1)"], "why": "Residues −1 at 0 and e at 1."}, {"q": "p(z) = z³ − z. How many roots inside |z − 1| = ½?", "a": "1", "w": ["0", "2", "3"], "why": "Only the root 1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26i"]=[{"q": "e^(i(α + β)) = e^(ia) e^(ib). Multiply out and read the floor parts. What do you get?", "a": "cos(α + β) = cos a cos β − sin a sin β", "w": ["cos(α + β) = cos a cos β + sin a sin β", "cos(α + β) = cos α + cos β", "cos(α + β) = cos a sin β − sin a cos β"], "why": "The part-reading technique: i sin α · i sin β = −sin a sin b lands in the floor part."}, {"q": "Which technique licenses the line e^(i(α + β)) = e^(ia) e^(ib)?", "a": "the plane-adding technique (26b1)", "w": ["the turn-growth technique (26a3)", "the sum technique (21d)", "the two-term-power technique (4k)"], "why": "Adding in the exponent becomes multiplying, for complex inputs; turn-growth only rewrites each factor as cos + i sin."}, {"q": "Two numbers of the plane are equal. What follows about their parts?", "a": "their floor parts agree and their upright parts agree", "w": ["only their sizes agree", "only their floor parts agree", "their parts agree after a turn"], "why": "Equal pairs have equal entries (25a); that is what the part-reading technique uses."}, {"q": "What is (cos θ + i sin θ)ⁿ for every whole n, negative n included?", "a": "cos nθ + i sin nθ", "w": ["cosⁿθ + i sinⁿθ", "n cos θ + i n sin θ", "cos θⁿ + i sin θⁿ"], "why": "The many-angle technique: (e^(iθ))ⁿ = e^(inθ) by the plane-adding technique."}, {"q": "Reading the floor part of (cos θ + i sin θ)³ and using sin² = 1 − cos², what is cos 3θ?", "a": "4cos³θ − 3cos θ", "w": ["3cos θ − 4cos³θ", "cos³θ − 3cos θ", "4cos³θ + 3cos θ"], "why": "Floor part c³ − 3cs², with s² = 1 − c²."}, {"q": "What is cos θ written with turns?", "a": "(e^(iθ) + e^(−iθ))/2", "w": ["(e^(iθ) − e^(−iθ))/2", "(e^(iθ) + e^(−iθ))/(2i)", "e^(iθ)/2"], "why": "The power-to-sum technique: a turn plus its flip is twice the cosine."}, {"q": "What is sin θ written with turns?", "a": "(e^(iθ) − e^(−iθ))/(2i)", "w": ["(e^(iθ) − e^(−iθ))/2", "(e^(iθ) + e^(−iθ))/(2i)", "(e^(−iθ) − e^(iθ))/(2i)"], "why": "The difference is 2i sin θ, so divide by 2i."}, {"q": "What is cos³θ as a sum of cosines?", "a": "(3cos θ + cos 3θ)/4", "w": ["cos 3θ", "(cos θ + 3cos 3θ)/4", "(3cos θ − cos 3θ)/4"], "why": "(e^(iθ) + e^(−iθ))³/8, flipped pairs joined into cosines."}, {"q": "What is the area of cos⁴θ over one whole turn, from 0 to 2π?", "a": "3π/4", "w": ["π/2", "3π/8", "0"], "why": "cos⁴θ = (3 + 4cos 2θ + cos 4θ)/8; the cos kθ pieces with k ≠ 0 have area 0 over a whole turn."}, {"q": "Find (1 + i√3)⁶.", "a": "64", "w": ["−64", "64i", "8"], "why": "1 + i√3 = 2e^(iπ/3); the sixth power is 64e^(2πi) = 64."}, {"q": "Why is cos²θ not the floor part of e^(2iθ)?", "a": "the floor part of a product is not the product of the floor parts", "w": ["it is, since cos θ is the floor part of e^(iθ)", "because e^(2iθ) has size 2", "because squares are never negative"], "why": "The floor part of (α + bi)² is α² − β², so cos 2θ = cos²θ − sin²θ."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26j"]=[{"q": "Where is 1 + z² zero in the plane?", "a": "at i and at −i", "w": ["nowhere", "at 1 and −1", "only at i"], "why": "(z − i)(z + i) = z² + 1, and a product is 0 only if a factor is."}, {"q": "Why does the sum of 1/(1 + x²) about 0 reach only 1?", "a": "its troubles ±i in the plane are at distance 1", "w": ["it blows up at x = ±1", "its pieces are all positive", "every power sum reaches 1"], "why": "The nearest-trouble technique; nothing goes wrong on the line itself."}, {"q": "f has a complex slope on |z − w| < R, with a real and f real on the floor. What does the plane-reach technique give?", "a": "the floor's sum of f about a reaches at least R", "w": ["the sum reaches exactly R", "the sum reaches at most R", "the sum reaches everywhere"], "why": "The plane's sum (26g2) has the same pieces as rung 23's sum, and settles on the whole disc."}, {"q": "A power sum equals f on |z − w| < d, and f has a pole at distance d from w. What does the pole-wall technique say?", "a": "the sum reaches at most d", "w": ["the sum reaches at least d", "the sum settles at the pole", "the sum reaches 2d"], "why": "Past the pole the sum would be continuous there, but f passes every ceiling near a pole."}, {"q": "What is the reach of the sum of 1/(1 + x²) about 3?", "a": "√10", "w": ["3", "1", "2"], "why": "The distance from 3 to ±i is √(3² + 1²)."}, {"q": "What is the reach of the sum of 1/(x² − 2x + 5) about 0?", "a": "√5", "w": ["2", "there is no limit, since the bottom has no root on the floor", "1"], "why": "The bottom is 0 at 1 ± 2i, of size √5."}, {"q": "Where is cos z zero in the plane?", "a": "only at π/2 + πk, on the floor", "w": ["also at points off the floor", "nowhere", "at 2πik"], "why": "cos z = 0 means e^(2iz) = −1, so 2iz = iπ + 2πik (the whole-turn technique)."}, {"q": "What is the exact reach of the sum of tan x about 0?", "a": "π/2", "w": ["π", "1", "π/4"], "why": "Plane-reach gives at least π/2 and the pole of tan at π/2 gives at most π/2."}, {"q": "Why can the plane-reach technique not be used for e^(−1/x²) about 0?", "a": "it has no complex slope near 0: along the upright it grows without a ceiling", "w": ["it is not smooth on the line", "its slopes at 0 are not all 0", "its sum wanders everywhere"], "why": "At z = it, |e^(−1/z²)| = e^(1/t²)."}, {"q": "The sum of 1/(x² + 1) about 0 at x = 1: what does it do?", "a": "it does not settle: its pieces are ±1", "w": ["it settles at ½", "it settles at 1", "it settles because 1 is not ±i"], "why": "At the reach itself anything can happen; here the shrink technique (22d) rules it out."}, {"q": "Which technique carries the reach from 1/(1 + x²) to arctan x?", "a": "the same-reach technique (23e2)", "w": ["the pole-wall technique", "the turn-growth technique", "the reach-by-ratio technique"], "why": "arctan's sum is the area sum of its slope's sum, and the two have the same reach."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26k"]=[{"q": "What is the half-disc loop H_R?", "a": "along the floor from −R to R, then back over the top on the half circle |z| = R", "w": ["the full circle |z| = R", "the half circle below the floor", "the floor from 0 to R and back"], "why": "Closing the line with a half circle over the top."}, {"q": "Which poles count in the total of f round H_R?", "a": "the poles above the floor of size less than R", "w": ["every pole of f", "the poles on the floor", "the poles below the floor"], "why": "The half-disc technique: poles below the floor or beyond the arc lie outside a disc holding the loop."}, {"q": "What is the total of 1/(1 + z²) round H_R for R > 1?", "a": "π", "w": ["0", "2π", "πi"], "why": "Only i counts; its residue is 1/(2i), and 2πi · 1/(2i) = π."}, {"q": "When does the arc's share fade, by the fading-arc technique?", "a": "when R times the largest |f| on the arc heads to 0", "w": ["when |f| heads to 0 on the arc", "when f has no poles", "when R grows"], "why": "The arc has length πR, so the path fence gives at most πR·M_R."}, {"q": "Find ∫ over the whole line of dx/(1 + x²).", "a": "π", "w": ["π/2", "2π", "1"], "why": "One residue above the floor, and the arc fades; the arctan agrees."}, {"q": "To find ∫ cos x/(1 + x²) over the line, which function goes round the loop?", "a": "e^(iz)/(1 + z²), then take the floor part", "w": ["cos z/(1 + z²)", "sin z/(1 + z²)", "e^(−iz)/(1 + z²)"], "why": "The upper-wave technique: |e^(iz)| ≤ 1 above the floor, while cos z grows there."}, {"q": "Find ∫ over the whole line of cos x/(1 + x²).", "a": "π/e", "w": ["π", "πe", "π/(2e)"], "why": "Res(e^(iz)/(1 + z²), i) = e^(−1)/(2i); 2πi times it is π/e."}, {"q": "Which line licenses |e^(iz)| = e^(−y) for z = x + iy?", "a": "the growth-and-turn technique (26b2)", "w": ["the turn-growth technique (26a3)", "the plane-size technique (26a1)", "the whole-turn technique (26b3)"], "why": "e^(a + bi) has size e^a; here a = −y. Turn-growth only covers real θ."}, {"q": "What does the sine-chord technique say on [0, π/2]?", "a": "sin t ≥ 2t/π", "w": ["sin t ≤ 2t/π", "sin t ≥ t", "sin t ≤ t/2"], "why": "sin t / t falls on (0, π/2], so it stays above its value 2/π at π/2."}, {"q": "Find ∫ from 0 to ∞ of sin x / x dx.", "a": "π/2", "w": ["π", "1", "it diverges"], "why": "Round H_R, (e^(iz) − 1)/z totals 0; the line gives 2i times the integral, and the arc gives −iπ plus a piece under π/R."}, {"q": "Does ∫ from 0 to ∞ of |sin x|/x dx converge?", "a": "no: it grows like a harmonic sum", "w": ["yes, to π/2", "yes, by comparison with 1/x", "yes, since sin x/x does"], "why": "Each hump from kπ to (k + 1)π adds at least 2/((k + 1)π)."}, {"q": "Why must the pole at −i be dropped from the total of 1/(1 + z²) round H_R?", "a": "it lies below the floor, outside the half-disc", "w": ["its residue is 0", "it is a pole of order 2", "it lies on the arc"], "why": "Counting it too gives 1/(2i) − 1/(2i) = 0, the wrong total."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26l"]=[{"q": "What is Γ(s), for s > 0?", "a": "∫ from 0 to ∞ of x^(s − 1) e^(−x) dx", "w": ["∫ from 0 to ∞ of xˢ e^(−x) dx", "∫ from 0 to 1 of x^(s − 1) e^(−x) dx", "the product 1 · 2 ⋯ s"], "why": "The definition; the two-ends technique proves it converges for every s > 0."}, {"q": "Why does the area for Γ(s) converge far out?", "a": "e^x ≥ x^m/m!, so x^(s − 1)e^(−x) ≤ m!/x² beyond 1", "w": ["because x^(s − 1) shrinks", "because e^(−x) is at most 1", "it converges only for whole s"], "why": "Growth beats every power; then comparison with 1/x²."}, {"q": "What is Γ(n + 1) for whole n ≥ 0?", "a": "n!", "w": ["(n + 1)!", "(n − 1)!", "n"], "why": "The factorial-step technique Γ(s + 1) = sΓ(s), from Γ(1) = 1."}, {"q": "Which technique gives Γ(s + 1) = sΓ(s)?", "a": "parts (16e), with the ends heading to 0", "w": ["substitution (16d)", "comparison for areas (16i3)", "the two-term power (4k)"], "why": "xˢ against the slope of −e^(−x); bˢe^(−b) and cˢe^(−c) both head to 0."}, {"q": "Find Γ(5).", "a": "24", "w": ["120", "5", "4"], "why": "Γ(5) = 4! by the factorial-step technique."}, {"q": "Find Γ(½).", "a": "√π", "w": ["½", "√π/2", "π"], "why": "With x = y², Γ(½) = 2∫₀^∞ e^(−y²) dy, and the bell-area technique gives that area as √π/2."}, {"q": "Between which two areas does the bell-area technique squeeze √n ∫₀^∞ e^(−nx²) dx?", "a": "√n I₂ₙ₊₁ and √n I₂ₙ₋₂, areas under powers of sin", "w": ["1 and 2", "n! and (n + 1)!", "π/4 and π/2"], "why": "(1 − x²)ⁿ ≤ e^(−nx²) ≤ (1 + x²)^(−n), with x = cos t and x = tan t."}, {"q": "Find ∫ over the whole line of e^(−x²/2) dx.", "a": "√(2π)", "w": ["√π", "2π", "1"], "why": "Stretch x = √2 y: √2 times √π."}, {"q": "How does the step-down technique give Γ(−½)?", "a": "Γ(½)/(−½) = −2√π", "w": ["by the area ∫ x^(−3/2)e^(−x) dx", "Γ(−½) = −Γ(½)", "it has no value"], "why": "Γ(s) = Γ(s + 1)/s, run below 0; the area itself diverges there."}, {"q": "At which s does Γ have no value?", "a": "0, −1, −2, …", "w": ["every negative s", "every s that is not whole", "only at 0"], "why": "The step-down technique divides by a factor that is 0 exactly there."}, {"q": "Γ(s + 1) + sin πs equals n! at every whole n. What does that show?", "a": "matching n! at the whole numbers does not fix a function between them", "w": ["that it equals Γ(s + 1)", "that Γ is wrong", "that sin πs is always 0"], "why": "More must be asked than the whole numbers to pick out Γ."}, {"q": "Two functions with complex slopes on |z − w| < R agree near w. What follows on that disc?", "a": "they agree on the whole disc", "w": ["they agree only near w", "they agree on the floor only", "nothing"], "why": "Same slopes at w, so the same pieces, and each is its own sum on the disc (26g2)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["26·cb24"]=[{"q": "r = α + iβ, x real. What is e^(rx), part by part?", "a": "e^(αx)(cos βx + i sin βx)", "w": ["e^(αx) + i e^(βx)", "e^(βx)(cos αx + i sin αx)", "cos αx + i sin βx"], "why": "26b's growth-and-turn: α sets the size, β the turn."}, {"q": "(e^(rx))′ for a complex rate r. Which technique licenses r e^(rx)?", "a": "the complex-rate technique", "w": ["the steady-swing technique", "the peak-ratio technique", "the light-brake technique"], "why": "Part by part, with the product technique and the slopes of sin and cos."}, {"q": "y″ + by′ + cy = 0 with b² < 4c. Every solution is …", "a": "e^(αx)(C₁ cos βx + C₂ sin βx), α = −b/2, β = √(c − b²/4)", "w": ["C₁e^(αx) + C₂e^(βx)", "(C₁ + C₂x)e^(αx)", "no real function: the roots are not real"], "why": "The decaying-turn technique, held in trust since 24h."}, {"q": "Why are the real and imaginary parts of a complex solution each solutions?", "a": "b and c are real, so the technique keeps the two parts apart", "w": ["every complex number is real", "the roots come in a pair", "the statement is second order"], "why": "(u″ + bu′ + cu) + i(v″ + bv′ + cv) = 0 with both brackets real."}, {"q": "y = e^(αx)w turns y″ + by′ + cy = 0 into which statement for w, when α = −b/2?", "a": "w″ = −β²w", "w": ["w′ = βw", "w″ = β²w", "w″ + bw′ = 0"], "why": "The shift that proves there are no other solutions."}, {"q": "A spring with a light brake, b < ω. Its pace is …", "a": "√(ω² − b²), a little slower than ω", "w": ["ω, unchanged", "ω − b", "√(ω² + b²), a little faster"], "why": "The light-brake technique."}, {"q": "Each swing of a lightly braked spring, as a share of the one before?", "a": "e^(−2πb/ω_d)", "w": ["e^(−b)", "1 − b/ω", "e^(−2πω_d/b)"], "why": "One period multiplies the envelope e^(−bt) by this."}, {"q": "E = ½(y′² + ω²y²) for y″ + 2by′ + ω²y = 0. What is E′?", "a": "−2by′²", "w": ["0", "−2bE", "−by²"], "why": "24h's flat energy now leaks through the brake."}, {"q": "Two peaks 10 cm and 6 cm, one period of 0.8 s apart. The damping b?", "a": "ln(5/3)/0.8 ≈ 0.64 per second", "w": ["(10 − 6)/0.8 = 5 per second", "ln(5/3) ≈ 0.51 per second", "0.6/0.8 = 0.75 per second"], "why": "The peak-ratio technique: log of the ratio, over the period."}, {"q": "More brake past b = ω. What does the spring do?", "a": "creeps back without swinging, slower than at b = ω", "w": ["settles faster and faster", "swings faster", "swings with a larger envelope"], "why": "Two real roots; the one nearer 0 dies slowly: 24h's door closer."}];
